#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SearchLimits {
    pub max_results: Option<usize>,
    pub max_bytes: usize,
    pub max_tokens: Option<usize>,
    pub max_candidates: usize,
