1712	fn parse_full(
1713	    analyzer: &TsAnalyzer,
1714	    path: &Utf8Path,
1715	    source: &str,
1716	    content_hash: ContentHash,
1717	    mtime_ns: u64,
1718	    size_bytes: u64,
1719	) -> FileAnalysis {
1720	    let allocator = Allocator::default();
1721	    let source_type = source_type_for(path);
1722	    let parsed = Parser::new(&allocator, source, source_type).parse();
1723	    let had_parse_errors = !parsed.errors.is_empty();
1724	    if had_parse_errors {
1725	        let details = parsed.errors.iter()
1726	            .map(std::string::ToString::to_string)
1727	            .collect::<Vec<_>>().join("; ");
1728	        warn!(path = %path, errors = %details, "parse errors encountered during analysis");
1729	    }
1730	    let mut symbols: Vec<SymbolEntry> = Vec::new();
1731	    let mut dependencies: Vec<DependencyRecord> = Vec::new();
1732	    let mut exports: Vec<ExportRecord> = Vec::new();
1733	    let mut jsx_elements: Vec<JsxElementEntry> = Vec::new();
1734	    let mut type_only_imports: Vec<String> = Vec::new();
1735	    let mut blocks: Vec<CodeBlock> = Vec::new();
1736	    for stmt in &parsed.program.body {
1737	        extract_stmt(analyzer, path, source, stmt,
1738	                    &mut symbols, &mut dependencies, &mut exports, &mut type_only_imports);
1739	        extract_jsx_from_stmt(source, stmt, &mut jsx_elements);
1740	        extract_block(path, source, stmt, &mut blocks);
1741	    }
1742	    drop(parsed);
1743	    drop(allocator);
1744	    let unresolved_aliases: Vec<String> = dependencies.iter()
1745	        .filter_map(|dep| match &dep.target {
1746	            crate::types::DependencyTarget::File { specifier, resolved, .. }
1747	                if resolved.is_none() && TsAnalyzer::looks_like_workspace_alias(specifier)
1748	                => Some(specifier.clone()),
1749	            _ => None,
1750	        }).collect();
