5696	
5697	```rust
5698	pub(crate) fn collect_exports(source: &str, tree: &SourceFile) -> Vec<ExportRecord> {
5699	    let mut exports = Vec::new();
5700	    for item in tree.items() {
5701	        match item {
5702	            ast::Item::Struct(strukt) if is_exported_item(&strukt) => { /* … */ }
5703	            ast::Item::Enum(enm) if is_exported_item(&enm) => { /* … */ }
5704	            ast::Item::Trait(trait_item) if is_exported_item(&trait_item) => { /* … */ }
5705	            ast::Item::Fn(func) if is_exported_item(&func) => { /* … */ }
5706	            ast::Item::TypeAlias(alias) if is_exported_item(&alias) => { /* … */ }
5707	            ast::Item::Const(konst) if is_exported_item(&konst) => { /* … */ }
5708	            ast::Item::Module(module) if is_exported_item(&module) => { /* … */ }
5709	            ast::Item::Use(use_item) => {
5710	                let line = byte_offset_to_line(source, use_item.syntax().text_range().start().into());
5711	                let text = use_item.syntax().text().to_string();
5712	                if let Some(rest) = text.trim().strip_prefix("pub use ") {
5713	                    for leaf in rust_analyzer::expand_use_clause(rest.trim_end_matches(';').trim()) {
5714	                        let (_, binding) = rust_analyzer::rust_binding(&leaf);
5715	                        exports.push(ExportRecord {
5716	                            name: binding.local,
5717	                            line,
5718	                            re_export: true,
5719	                        });
5720	                    }
5721	                }
5722	            }
5723	            _ => {}
5724	        }
5725	    }
5726	    exports
5727	}
