6170	### Ref validation
6171	
6172	```rust
6173	pub(crate) fn validate_git_ref(r: &str) -> Result<()> {
6174	    if r.is_empty() {
6175	        return Err(MonoklError::InvalidGitRef { ref_: r.to_owned(), reason: "ref is empty" });
6176	    }
6177	    if r.starts_with('-') {
6178	        return Err(MonoklError::InvalidGitRef {
6179	            ref_: r.to_owned(),
6180	            reason: "starts with '-' — refusing as it could be parsed as a git option",
6181	        });
6182	    }
6183	    let ok = r.chars().all(|c| {
6184	        matches!(c, 'A'..='Z' | 'a'..='z' | '0'..='9' | '_' | '/' | '.' | '@' | '{' | '}' | '^' | '~' | ':' | '+' | '-')
6185	    });
6186	    if !ok {
6187	        return Err(MonoklError::InvalidGitRef {
6188	            ref_: r.to_owned(),
6189	            reason: "contains characters outside the safe set",
6190	        });
6191	    }
6192	    Ok(())
6193	}
6194	```
