6840	            if !opts.allow_tests && is_test_path(&path) { continue; }
6841	            if supports(&path) { files.push(path); }
6842	        }
6843	    }
6844	    files.sort();
6845	    files.dedup();
6846	    Ok(files)
6847	}
6848	
6849	pub fn is_test_path(path: &Utf8Path) -> bool {
6850	    let s = path.as_str();
6851	    s.contains("/__tests__/")
6852	        || s.contains("/test/")
6853	        || s.contains("/tests/")
6854	        || s.contains("/spec/")
6855	        || s.ends_with(".test.ts")
6856	        || s.ends_with(".test.tsx")
6857	        || s.ends_with(".test.js")
6858	        || s.ends_with(".spec.ts")
6859	        || s.ends_with(".spec.tsx")
6860	        || s.ends_with(".spec.js")
6861	}
6862	
6863	fn supports_requested_language(registry: &AnalyzerRegistry, path: &Utf8Path, languages: Option<&[LanguageId]>) -> bool {
6864	    match languages {
6865	        Some(languages) => registry.supports_language(path, languages),
6866	        None => registry.supports(path),
6867	    }
6868	}
6869	
6870	pub fn candidate_language(path: &Utf8Path) -> Option<LanguageId> {
6871	    match path.extension().unwrap_or("").to_ascii_lowercase().as_str() {
6872	        "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" | "mts" | "cts" => Some(LanguageId::TypeScript),
6873	        "rs" => Some(LanguageId::Rust),
6874	        "py" | "pyi" => Some(LanguageId::Python),
6875	        "cs" => Some(LanguageId::CSharp),
6876	        _ => None,
6877	    }
6878	}
6879	
6880	pub fn is_candidate_source_file(path: &Utf8Path) -> bool {
6881	    candidate_language(path).is_some()
6882	}
6883	```
6884	
6885	`is_candidate_source_file` lets workspace-wide commands like `classify` and `migration-surface` honestly count Python and C# files toward `total` while emitting `unsupported` diagnostics for them, rather than silently dropping them and overstating adoption.
