174	
175	## 2b. `TsAnalyzer`'s completed trait impl
176	
177	Before the registry below can hold `Arc<dyn LanguageAnalyzer>`, `TsAnalyzer` needs the
178	`language_id`/`capabilities` methods §11's trait now declares. `analyze` (§17) becomes
179	`analyze_with_profile`, rebuilt on top of §2a's shared helper — v0.1.0's cache logic is
180	unchanged, TS just always answers `Some`/`true` since it does a full parse regardless of profile:
181	
182	```rust
183	impl LanguageAnalyzer for TsAnalyzer {
184	    fn language_id(&self) -> LanguageId {
185	        LanguageId::TypeScript
186	    }
187	
188	    fn supports(&self, path: &Utf8Path) -> bool {
189	        if path.as_str().ends_with(".d.ts") { return false; }
190	        matches!(path.extension(), Some("ts" | "tsx" | "js" | "jsx" | "mts" | "cts" | "mjs" | "cjs"))
191	    }
192	
193	    fn capabilities(&self) -> AnalyzerCapabilities {
194	        AnalyzerCapabilities {
195	            blocks: true,
196	            classified_imports: true,
197	            resolved_import_graph: CapabilityPrecision::Exact,
198	            refs: CapabilityPrecision::Structural,
199	            definition: CapabilityPrecision::Structural,
200	            inspect_detail: CapabilityPrecision::Structural,
201	        }
202	    }
203	
204	    fn analyze_with_profile(
205	        &self,
206	        path: &Utf8Path,
207	        source: Box<dyn FnOnce() -> Result<String>>,
208	        profile: AnalysisProfile,
209	    ) -> Result<Arc<FileAnalysis>> {
210	        cache_tiers::lookup_or_parse(
211	            path,
212	            source,
213	            profile,
214	            |persisted, _profile| Some(analysis_from_persisted(path, persisted)),
215	            |_cached, _profile| true,
216	            |src, hash, mtime_ns, size_bytes, _profile| {
217	                parse_full(self, path, src, hash, mtime_ns, size_bytes)
218	            },
219	        )
220	    }
221	}
222	```
223	
224	TS/JS always does a full parse regardless of `profile`, since `parse_full` produces
225	symbols/dependencies/exports/blocks in one OXC pass at no extra marginal cost — unlike Rust's
226	AST-vs-regex-fallback split, where a `Dependencies`-only request genuinely skips work, TS has no
227	cheaper partial path to offer, so `from_persisted`/`cached_is_valid` always answer "yes."
228	`resolved_import_graph: CapabilityPrecision::Exact` reflects `oxc_resolver`'s real module
229	resolution, not a heuristic — the only analyzer in this spec entitled to `Exact` on that field.
230	
231	---
232	
233	## 3. Analyzer Registry (`analysis/registry.rs`)
234	
235	The `AnalyzerRegistry` is the architectural boundary for mixed-language workspaces. Callers ask the registry which analyzer owns a path instead of hardcoding `TsAnalyzer` plus ad hoc `.rs` exceptions.
236	
237	```rust
238	//! Multi-language analyzer registry.
239	//!
240	//! This is the architectural boundary for mixed-language workspaces. Callers
241	//! ask the registry which analyzer owns a file instead of hardcoding
242	//! `TsAnalyzer` plus ad hoc `.rs` exceptions.
243	
244	use std::sync::Arc;
245	
246	use camino::Utf8Path;
247	
248	use crate::error::Result;
249	use crate::types::WorkspaceOptions;
250	
251	#[cfg(feature = "lang-ts")]
252	use super::TsAnalyzer;
253	use super::{LanguageAnalyzer, LanguageId, RustAnalyzer};
254	
255	pub struct AnalyzerRegistry {
256	    analyzers: Vec<Arc<dyn LanguageAnalyzer>>,
257	    config_hash: String,
258	}
259	
260	impl AnalyzerRegistry {
261	    pub fn from_workspace_opts(opts: &WorkspaceOptions) -> Result<Self> {
262	        let mut analyzers: Vec<Arc<dyn LanguageAnalyzer>> = Vec::new();
263	        let mut hash_parts: Vec<String> = Vec::new();
264	
265	        #[cfg(feature = "lang-ts")]
266	        {
267	            analyzers.push(Arc::new(TsAnalyzer::from_workspace_opts(opts)?));
268	            hash_parts.push(TsAnalyzer::config_hash_for(opts));
269	        }
270	
271	        analyzers.push(Arc::new(RustAnalyzer::from_workspace_opts(opts)));
272	        hash_parts.push("rust-analyzer-v1".to_owned());
273	
274	        Ok(Self {
275	            analyzers,
276	            config_hash: hash_parts.join("::"),
277	        })
278	    }
279	
280	    pub fn config_hash(&self) -> &str {
281	        &self.config_hash
282	    }
283	
284	    pub fn analyzers(&self) -> &[Arc<dyn LanguageAnalyzer>] {
285	        &self.analyzers
286	    }
287	
288	    pub fn supports(&self, path: &Utf8Path) -> bool {
289	        self.analyzer_for(path).is_some()
290	    }
291	
292	    pub fn analyzer_for(&self, path: &Utf8Path) -> Option<&dyn LanguageAnalyzer> {
293	        self.analyzers
294	            .iter()
295	            .find(|analyzer| analyzer.supports(path))
296	            .map(Arc::as_ref)
297	    }
298	
299	    pub fn supports_language(&self, path: &Utf8Path, languages: &[LanguageId]) -> bool {
300	        self.analyzer_for(path)
301	            .is_some_and(|analyzer| languages.contains(&analyzer.language_id()))
